<script lang="ts">
	import { getCurrentThemeColor } from '$lib/utils';
	import { onMount } from 'svelte';
	import Matter from 'matter-js';
	import SimCard from './sections/SimCard.svelte';
	import Twitter from './icons/Twitter.svelte';
	import Telegram from './icons/Telegram.svelte';
	import GitHub from './icons/GitHub.svelte';
	import Email from './icons/Email.svelte';

	let container: HTMLDivElement;

	let canvas: HTMLCanvasElement;
	let ctx: CanvasRenderingContext2D;

	let clicking = false;

	let mousePos = { x: 0, y: 0 };

	let bodies: Matter.Body[] = [];
	let domBodies: Matter.Body[] = [];

	let { Engine, Bodies, Runner, Composite } = Matter;

	const engine = Engine.create();
	const runner = Runner.create();

	Runner.run(runner, engine);

	function handleMouseOver(e: any) {
		const rect = container.getBoundingClientRect();

		mousePos = {
			x: e.clientX - rect.left,
			y: e.clientY - rect.top
		};
	}

	onMount(() => {
		let textObserver = new IntersectionObserver(
			(entries) => {
				entries.forEach((entry) => {
					if (entry.isIntersecting && entry.target.dataset.type == 'blur-svg')
						entry.target.classList.add('show-blur');

					if (entry.isIntersecting && entry.target.dataset.type == 'text-svg')
						entry.target.classList.add('show-text');
				});
			},
			{
				threshold: 1
			}
		);

		let texts = document.querySelectorAll('.text-observe');
		texts.forEach((text) => {
			textObserver.observe(text);
		});

		ctx = canvas.getContext('2d') as CanvasRenderingContext2D;

		window.addEventListener('mousemove', handleMouseOver);
		window.addEventListener('touchmove', handleMouseOver);

		window.addEventListener('mousedown', setClickingTrue);
		window.addEventListener('touchstart', setClickingTrue);

		window.addEventListener('mouseup', setClickingFalse);
		window.addEventListener('touchend', setClickingFalse);

		let physicals = document.querySelectorAll('.physical');

		function setCanvasSize() {
			canvas.width = canvas.parentElement?.clientWidth as number;
			canvas.height = canvas.parentElement?.clientHeight as number;
		}

		setCanvasSize();

		function adjustDomBodies() {
			domBodies.forEach((body, index) => {
				let parentProps = container.getBoundingClientRect();
				let props = physicals[index].getBoundingClientRect();

				Matter.Body.setPosition(body, {
					x: props.x + props.width / 2,
					y: Math.abs(parentProps.y - props.y) + props.height / 2
				});
			});
		}

		function handleResize() {
			setCanvasSize();
			adjustDomBodies();
		}

		window.addEventListener('resize', handleResize);

		physicals.forEach((element) => {
			let parentProps = container.getBoundingClientRect();
			let props = element.getBoundingClientRect();

			let body = Bodies.rectangle(
				props.x + props.width / 2,
				Math.abs(parentProps.y - props.y) + props.height / 2,
				props.width,
				props.height,
				{
					isStatic: true
				}
			);

			domBodies.push(body);
			Composite.add(engine.world, [body]);
		});

		requestAnimationFrame(loop);
	});

	let setClickingFalse = () => (clicking = false);
	let setClickingTrue = (e) => {
		clicking = true;
	};

	function addBody() {
		let body = Bodies.circle(mousePos.x, mousePos.y, 10, { restitution: 1 });
		Composite.add(engine.world, [body]);
		bodies.push(body);
	}

	function drawShape(x: number, y: number, radius: number) {
		ctx.beginPath();
		ctx.fillStyle = getCurrentThemeColor();
		ctx.arc(x, y, radius, 0, Math.PI * 2, false);
		ctx.fill();
	}

	function loop() {
		ctx.clearRect(0, 0, canvas.width, canvas.height);

		if (clicking) {
			addBody();
		}

		bodies.forEach((body) => {
			drawShape(body.position.x, body.position.y, body.circleRadius as number);
		});

		requestAnimationFrame(loop);
	}
</script>

